```python
def somme_pairs(n):
    return sum(i for i in range(0, n+1) if i % 2 == 0)
```

```python
def compter_voyelles(s):
    voyelles = 'aeiouyAEIOUY'
    return sum(1 for char in s if char in voyelles)
```

```python
def max_liste(l):
    if not l:
        return None
    max_element = l[0]
    for element in l:
        if element > max_element:
            max_element = element
    return max_element
```

```python
def fizzbuzz(n):
    result = []
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
```

```python
def moyenne(l):
    return round(sum(l) / len(l), 2)
```

```python
def mots_uniques(phrase):
    return set(word.lower() for word in phrase.split())
```

```python
def facteur(n):
    if n == 0:
        return 1
    else:
        return n * facteur(n-1)
```

```python
def tri_bulles(l):
    n = len(l)
    for i in range(n):
        for j in range(0, n-i-1):
            if l[j] > l[j+1]:
                l[j], l[j+1] = l[j+1], l[j]
    return l
```

```python
def fib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
```

```python
def freq_chars(s):
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency
```

```python
def convertir_octets(n):
    if n < 1024:
        return f"{n} octets"
    elif n < 1024**2:
        return f"{n / 1024:.2f} Ko"
    elif n < 1024**3:
        return f"{n / 1024**2:.2f} Mo"
    else:
        return f"{n / 1024**3:.2f} Go"
```

```python
def anagramme(a, b):
    return sorted(a.lower()) == sorted(b.lower())
```

```python
def lire_csv(texte):
    lignes = texte.strip().split('\n')
    dictionnaire = {}
    for ligne in lignes:
        cle, valeur = ligne.split(',')
        dictionnaire[cle] = valeur
    return dictionnaire
```

```python
def dichotomie(l, x):
    debut = 0
    fin = len(l) - 1

    while debut <= fin:
        milieu = (debut + fin) // 2
        if l[milieu] == x:
            return milieu
        elif l[milieu] < x:
            debut = milieu + 1
        else:
            fin = milieu - 1

    return -1
```

```python
def devise(n):
    return f"{n:,.0f} €".replace(',', ' ')
```

```python
def supprimer_doublons(l):
    seen = set()
    result = []
    for item in l:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result
```

```python
def est_premier(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
```
